// [S3] Mirrors persisted triage state labels without exposing internal output.
import 'package:family_veda/theme/app_theme.dart';
import 'package:flutter/material.dart';

enum _StepState { complete, current, upcoming }

class StatusStepper extends StatelessWidget {
  const StatusStepper({super.key, required this.status});

  static const _steps = [
    ('SUBMITTED', 'Request received'),
    ('PLANNING', 'Preparing your request'),
    ('PENDING_DOCTOR_REVIEW', 'Doctor review'),
    ('APPROVED', 'Guidance approved'),
  ];
  static int get stepCount => _steps.length;
  static int indexOf(String status) => switch (status) {
    'PLANNING' ||
    'CONTEXT_READY' ||
    'ANALYSED' ||
    'RISK_ASSESSED' ||
    'VALIDATED' => 1,
    'PENDING_DOCTOR_REVIEW' || 'CLAIMED' || 'LOW_CONFIDENCE' => 2,
    'APPROVED' || 'APPROVED_REVISED' || 'DELIVERED' || 'CLOSED' => 3,
    _ => 0,
  };

  final String status;

  @override
  Widget build(BuildContext context) {
    final active = indexOf(status);
    final finished = active == _steps.length - 1;
    return Column(
      children: [
        for (var index = 0; index < _steps.length; index++)
          _StepRow(
            number: index + 1,
            total: _steps.length,
            label: _steps[index].$2,
            state: index < active || finished
                ? _StepState.complete
                : index == active
                ? _StepState.current
                : _StepState.upcoming,
            isLast: index == _steps.length - 1,
          ),
      ],
    );
  }
}

class _StepRow extends StatelessWidget {
  const _StepRow({
    required this.number,
    required this.total,
    required this.label,
    required this.state,
    required this.isLast,
  });

  static const double _node = 30;

  final int number;
  final int total;
  final String label;
  final _StepState state;
  final bool isLast;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final success = context.glass.success;
    final accent = switch (state) {
      _StepState.complete => success,
      _StepState.current => scheme.primary,
      _StepState.upcoming => scheme.outlineVariant,
    };
    final filled = state != _StepState.upcoming;
    // State is spoken and shown as text, never left to colour alone.
    final stateText = switch (state) {
      _StepState.complete => 'Done',
      _StepState.current => 'In progress',
      _StepState.upcoming => 'Up next',
    };

    return Semantics(
      container: true,
      label: 'Step $number of $total, $label, $stateText',
      child: ExcludeSemantics(
        child: IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Column(
                children: [
                  Container(
                    width: _node,
                    height: _node,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: filled ? accent : scheme.surface,
                      border: Border.all(color: accent, width: 2),
                      boxShadow: state == _StepState.current
                          ? [
                              BoxShadow(
                                color: accent.withValues(alpha: 0.22),
                                spreadRadius: 4,
                              ),
                            ]
                          : null,
                    ),
                    child: state == _StepState.complete
                        ? const Icon(Icons.check, size: 16, color: Colors.white)
                        : Text(
                            '$number',
                            style: theme.textTheme.labelMedium?.copyWith(
                              fontWeight: FontWeight.w700,
                              color: filled
                                  ? Colors.white
                                  : scheme.onSurfaceVariant,
                            ),
                          ),
                  ),
                  if (!isLast)
                    Expanded(
                      child: Container(
                        width: 2,
                        margin: const EdgeInsets.symmetric(vertical: 4),
                        decoration: BoxDecoration(
                          color: state == _StepState.complete
                              ? success
                              : scheme.outlineVariant,
                          borderRadius: BorderRadius.circular(2),
                        ),
                      ),
                    ),
                ],
              ),
              const SizedBox(width: 14),
              Expanded(
                child: Padding(
                  padding: EdgeInsets.only(top: 4, bottom: isLast ? 0 : 18),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        label,
                        style: theme.textTheme.titleSmall?.copyWith(
                          fontWeight: state == _StepState.upcoming
                              ? FontWeight.w500
                              : FontWeight.w600,
                          color: state == _StepState.upcoming
                              ? scheme.onSurfaceVariant
                              : scheme.onSurface,
                        ),
                      ),
                      if (state == _StepState.current) ...[
                        const SizedBox(height: 2),
                        Text(
                          stateText,
                          style: theme.textTheme.bodySmall?.copyWith(
                            color: scheme.primary,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
